import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        k = int(next(iterator))
    except StopIteration:
        return

    main_courses = set()
    for _ in range(k):
        main_courses.add(int(next(iterator)))

    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        try:
            t = int(next(iterator))
            for _ in range(t):
                dep = int(next(iterator))
                adj[dep].append(i)
                in_degree[i] += 1
        except StopIteration:
            break

    needed = set(main_courses)
    queue = deque()

    for course in main_courses:
        if in_degree[course] == 0:
            queue.append(course)

    result = []
    visited = set()

    while queue:
        u = queue.popleft()
        if u in visited:
            continue
        visited.add(u)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0 and v in needed:
                queue.append(v)

    if len(visited) != len(main_courses):
        print("-1")
        return

    print(len(result))
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    solve()
